using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.TwistedGround;

internal sealed class OriginalGaussianSourceRestrictionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianSourceRestriction.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "OriginalGaussianSourceRestriction", H("Frequency restriction after full inverse colour transport"), Blocks(
            Paragraph(Text("The inverse substitution is diagonal only in frequency. At each frequency its action still sums over every original colour. Expanding this action proves that full right covariance and opposite-charge mean entries restrict across nested frequency boxes. Both mixed rectangles and the external block are included. Native affine coefficient enlargement then gives full-row stabilization while retaining each external occupation in its row degree. Empty colour, frequency and external types are in scope. The original Wick contraction is also reduced to one arbitrary common box that contains the fixed external supports and the energy layer. The compact four-support external family is embedded in any containing common box, preserving the full original rows for subsequent ordinary extraction.")),
            Describe.Lean(DescribeId.Create("original-source-internal-inclusion"), DeclarationHandle.Create(Prefix + "internalInclusion"), H("Colour-preserving frequency inclusion"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The embedding retains every colour and the value of each positive frequency in a larger frequency box."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-boxexternal"), DeclarationHandle.Create(Prefix + "boxExternal"), H("Common-box external labels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The two copies of the box index label input and output coordinates."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-foursupport"), DeclarationHandle.Create(Prefix + "fourSupport"), H("Four fixed external supports"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The union of the two input and two output supports is finite."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-compactexternal-type"), DeclarationHandle.Create(Prefix + "CompactExternal"), H("Compact external coordinate family"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Two copies of the support distinguish input and output labels."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-compactexternal"), DeclarationHandle.Create(Prefix + "compactExternal"), H("Actual compact external labels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The compact labels retain the literal input or output flag and original colour and frequency."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-externaloccupation"), DeclarationHandle.Create(Prefix + "externalOccupation"), H("Four fixed occupations"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The full external occupation stores left input, left output, right input and right output in that order."))), DescribeRole.Definition),
            N("original_right_covariance_restrict", "Complete transported covariance restriction", "All four internal and external block cases use the actual complete inverse colour transport before restriction. The finite colour sums are identical at retained frequencies."),
            N("original_right_mean_restrict", "Opposite-charge mean restriction", "The complete inverse transport of the original mean at charge minus a commutes with nested frequency-box restriction."),
            N("original_external_box_coefficients", "External box reindexing", "An arbitrary embedded finite external family identifies both original common-box row coefficients with their actual full native source rows. Complete colour sums are taken before frequency restriction."),
            N("original_compact_box_coefficients", "Four-support common-box rows", "The compact input and output supports embed into any common frequency box containing the support. The two native coefficients equal the corrected common-box occupations, including the full opposite-charge right transport."),
            N("original_fixed_energy_compact", "Original fixed energy in compact external coordinates", "The original Wick energy finsum equals its compact full native row layer in every sufficiently large common box. Both charge scalars, four external factorials, one internal factorial and both literal Laurent selectors remain unchanged."),
            N("original_fixed_energy_common_box", "Original Wick contraction in one common box", "For every common box strictly larger than n and containing all four external supports, the original fixed-energy Wick contraction equals its native affine energy layer. Both charge scalars, all four external factorials and both integer Laurent selectors remain literal. The right covariance and opposite-charge mean use the complete original inverse colour transport before any restriction.")), []));

    private static DocumentBlock N(string name, string title, string prose) =>
        Describe.Lean(DescribeId.Create("original-gaussian-sourcerestriction-" + name.Replace("_", "-")),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), DescribeRole.Theorem);
}
